(function (global) {
  class Chart {
    constructor(canvas, config) {
      this.canvas = canvas;
      this.ctx = canvas.getContext("2d");
      this.config = config;
      this.render();
    }
    render() {
      const c = this.canvas,
        ctx = this.ctx,
        dpr = global.devicePixelRatio || 1,
        w = c.clientWidth || 640,
        h = c.clientHeight || 320;
      c.width = w * dpr;
      c.height = h * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);
      const data = this.config.data || {},
        labels = data.labels || [],
        sets = data.datasets || [],
        pad = { l: 96, r: 38, t: 28, b: 48 },
        plotW = w - pad.l - pad.r,
        plotH = h - pad.t - pad.b,
        max = Math.max(1, ...sets.flatMap((s) => s.data || [])) * 1.12;
      ctx.font = "700 15px Inter, system-ui, sans-serif";
      ctx.textBaseline = "middle";
      labels.forEach((label, i) => {
        const rowH = plotH / labels.length,
          y = pad.t + i * rowH + rowH / 2,
          bh = Math.min(30, rowH * 0.42);
        ctx.fillStyle = "#334155";
        ctx.textAlign = "right";
        ctx.fillText(label, pad.l - 18, y);
        sets.forEach((set, j) => {
          const val = set.data[i] || 0,
            x = pad.l,
            width = plotW * (val / max),
            off = ((j - (sets.length - 1) / 2) * (bh + 5)) / sets.length;
          const grad = ctx.createLinearGradient(x, 0, x + plotW, 0);
          (set.backgroundColor || ["#2563eb", "#06b6d4"]).forEach(
            (color, idx, arr) =>
              grad.addColorStop(
                arr.length === 1 ? 1 : idx / (arr.length - 1),
                color,
              ),
          );
          roundRect(
            ctx,
            x,
            y - bh / 2 + off,
            width,
            bh / sets.length + 0.5,
            10,
            grad,
          );
          ctx.fillStyle = "#0f172a";
          ctx.textAlign = "left";
          ctx.fillText(String(val), x + width + 10, y + off);
        });
      });
      ctx.strokeStyle = "rgba(15,23,42,.12)";
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(pad.l, pad.t);
      ctx.lineTo(pad.l, pad.t + plotH);
      ctx.lineTo(pad.l + plotW, pad.t + plotH);
      ctx.stroke();
      ctx.fillStyle = "#64748b";
      ctx.textAlign = "center";
      ctx.textBaseline = "alphabetic";
      ctx.font = "800 13px Inter, system-ui, sans-serif";
      ctx.fillText(
        this.config.options?.plugins?.title?.text || "",
        w / 2,
        h - 14,
      );
    }
  }
  function roundRect(ctx, x, y, w, h, r, fill) {
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + w, y, x + w, y + h, r);
    ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r);
    ctx.arcTo(x, y, x + w, y, r);
    ctx.closePath();
    ctx.fillStyle = fill;
    ctx.fill();
  }
  global.Chart = Chart;
})(window);
